// Tecton · Construtora e empreiteira: obras e etapas (Gantt simples, % físico e financeiro), orçamento por etapa com BDI,
// medições, aditivos aprovados pelo cliente, equipes e diárias, compras por obra, diário com fotos, resultado da obra
// (orçado x realizado), contratos e documentos e o link para o cliente acompanhar.
import { db, grava, tela, acao, ir, cab, vazio, barra, ico, t, R$, R0, n2, pc, dataBR, dataCurta, quando, hoje, somaDias, dias, uid, soma, num,
  folha, editar, campos, lerCampos, toast, confirma, $, $$, pessoa, nomeDe, whatsapp, imprimir, reduzir, CONTA } from './nucleo.js?v=4';
import { PAINEIS, numero, saudacao, ORIGENS, RELACIONADOS, BUSCAS, darBaixa, movimentos, vencido, doMes, editarPessoa } from './comum.js?v=4';
import { pl, ouvir } from './nucleo.js?v=4';

const R = 'construtora';
const obra = (id) => db.obras.find((o) => o.id === id);
const TIPOS = { material: 'Material', mao: 'Mão de obra', equip: 'Equipamento' };
const custoEtapa = (o, et) => soma(o.orc.filter((i) => i.etapa === et), (i) => i.qtd * i.unit);
export const custoOrc = (o) => soma(o.orc, (i) => i.qtd * i.unit);
const vendaEtapa = (o, et) => custoEtapa(o, et) * (1 + (o.bdi || 0) / 100);
const vendaOrc = (o) => custoOrc(o) * (1 + (o.bdi || 0) / 100);
const aditivosOk = (o) => soma(o.aditivos.filter((a) => a.status === 'aprovado'), (a) => a.valor);
export const contrato = (o) => (o.valor || 0) + aditivosOk(o);
export function fisico(o) {
  const tot = soma(o.etapas, (e) => vendaEtapa(o, e.id));
  if (!o.etapas.length) return 0;
  return tot > 0 ? soma(o.etapas, (e) => e.pct * vendaEtapa(o, e.id)) / tot : soma(o.etapas, (e) => e.pct) / o.etapas.length;
}
const finObra = (o) => db.fin.filter((f) => f.obra === o.id);
const aReceberTxt = (o) => { const l = finObra(o).filter((f) => f.tipo === 'receber' && !f.pago); return l.length ? `falta receber (já aprovado): ${R$(soma(l, (f) => f.valor))}${l.length > 1 ? ` = ${l.map((f) => `${f.desc.replace(` · ${o.nome}`, '').split(' · ')[0].toLowerCase()} ${R$(f.valor)}`).join(' + ')}` : ''}` : 'nada aprovado a receber'; };
export const recebido = (o) => soma(finObra(o).filter((f) => f.tipo === 'receber' && f.pago), (f) => f.valor);
export const financeiro = (o) => (contrato(o) ? recebido(o) / contrato(o) * 100 : 0);
const custoDiaria = (a) => a.dias * (db.trab.find((x) => x.id === a.trab)?.diaria || 0);
const diariasAbertas = (o) => soma(db.apont.filter((a) => a.obra === o.id && !a.fechado), custoDiaria);
export const perdasObra = (o) => soma(db.pedidos.filter((p) => p.obra === o.id), (p) => soma(p.itens, (i) => (i.perda || 0) * i.unit));
// gasto da obra: contas a pagar da obra (pagas ou não) + diárias apontadas que ainda não foram lançadas no financeiro
function realizado(o) {
  const pg = finObra(o).filter((f) => f.tipo === 'pagar');
  const mo = (f) => /m[ãa]o de obra|di[áa]ria|empreit/i.test(f.cat || ''), eqp = (f) => /equip|seguro|aluguel|locad/i.test(`${f.cat} ${f.desc}`);
  const emp = (f) => /empreit/i.test(f.cat || ''), proprias = soma(pg.filter((f) => mo(f) && !emp(f)), (f) => f.valor) + diariasAbertas(o), empreit = soma(pg.filter(emp), (f) => f.valor);
  const por = { mao: proprias + empreit, proprias, empreit, equip: soma(pg.filter((f) => !mo(f) && eqp(f)), (f) => f.valor), material: soma(pg.filter((f) => !mo(f) && !eqp(f)), (f) => f.valor) };
  return { ...por, total: por.material + por.equip + por.mao };
}
// quanto já deveria ter sido gasto para o % físico de cada etapa (custo orçado da etapa × % feito)
const previsto = (o) => soma(o.etapas, (e) => custoEtapa(o, e.id) * e.pct / 100);
const atrasoDias = (o) => (o.status === 'andamento' && o.fim < hoje() ? dias(o.fim, hoje()) : 0);
const STATUS = { orcamento: ['Em orçamento', 'info'], andamento: ['Em andamento', 'pri'], parada: ['Parada', 'atn'], entregue: ['Entregue', 'ok'] };
const fotoObra = (o) => o.foto || o.diario.find((d) => d.fotos?.length)?.fotos[0] || '';
export const MODELOS = {
  residencial: ['Residencial', [['Serviços preliminares', 10], ['Fundação', 25], ['Estrutura', 40], ['Alvenaria', 35], ['Cobertura', 20], ['Instalações', 35], ['Acabamento', 45]]],
  galpao: ['Galpão', [['Terraplenagem', 12], ['Fundação', 25], ['Estrutura metálica', 40], ['Cobertura', 25], ['Fechamento lateral', 20], ['Piso industrial', 20], ['Instalações', 20]]],
  reforma: ['Reforma comercial', [['Aprovação do projeto', 10], ['Demolição', 6], ['Instalações', 15], ['Drywall e forro', 12], ['Revestimentos', 14], ['Pintura', 8], ['Limpeza e entrega', 3]]],
};

// ------------------------------------------------------------------ painel
PAINEIS[R] = {
  // cada pedaço do painel é um bloco: o painel monta só os blocos que a pessoa escolheu (Ajustar o Tecton para mim)
  padrao: ['k-obras', 'k-receber', 'k-pagar', 'k-equipe', 'obras', 'atencao', 'cronograma', 'canteiro'],
  nomes: { 'k-obras': 'Obras em andamento (número)', 'k-receber': 'A receber este mês (número)', 'k-pagar': 'A pagar este mês (número)', 'k-equipe': 'Equipe hoje (número)', 'k-lucro': 'Lucro previsto das obras (número)', obras: 'Lista das obras', atencao: 'Pede atenção', cronograma: 'Cronograma', canteiro: 'Hoje no canteiro (fotos)', resultado: 'Lucro de cada obra', medicoes: 'Medições e cobrança', semana: 'Diárias da semana', compras: 'Material para chegar', cliente: 'Notícia para o cliente', orcamentos: 'Orçamentos em aberto' },
  cab() { return `<div class="cab"><div><h1>${saudacao()}, ${t(db.config.nome || 'construtora')}</h1><p>${t(db.config.cidade || '')}${db.config.uf ? '/' + t(db.config.uf) : ''} · ${dataBR(hoje())}</p></div><div class="linha-bts"><button type="button" class="bt" data-ir="diario">${ico('foto')}Diário de hoje</button><button type="button" class="bt cheio" data-acao="obra-nova">${ico('mais2')}Nova obra</button></div></div>`; },
  blocos() {
    const and = db.obras.filter((o) => o.status === 'andamento'), ms = movimentos(), orcO = db.obras.filter((o) => o.status === 'orcamento');
    const rec = ms.filter((m) => m.tipo === 'receber' && !m.pago && (doMes(m) || vencido(m))), pag = ms.filter((m) => m.tipo === 'pagar' && !m.pago && (doMes(m) || vencido(m)));
    const hojeAp = db.apont.filter((a) => a.dia === hoje());
    const risco = (o) => { const p = previsto(o), g = realizado(o).total; return p > 0 && g > p * 1.05 ? (g - p) / p * 100 : 0; };
    const lucro = (o) => contrato(o) - custoOrc(o);
    return {
      'k-obras': { tipo: 'kpi', html: () => numero('capacete', 'Obras', `${and.length} em andamento`, orcO.length ? `+ ${pl(orcO.length, 'em orçamento', 'em orçamento')}: ${t(orcO.map((o) => o.nome).join(', '))}` : 'nenhuma em orçamento', 'obras') },
      'k-receber': { tipo: 'kpi', html: () => numero('dinheiro', 'A receber este mês', R0(soma(rec, (m) => m.valor)), pl(rec.length, 'recebimento', 'recebimentos'), 'financeiro/receber') },
      'k-pagar': { tipo: 'kpi', html: () => numero('conta', 'A pagar este mês', R0(soma(pag, (m) => m.valor)), pag.some(vencido) ? `${R0(soma(pag.filter(vencido), (m) => m.valor))} já vencido` : 'nada vencido', 'financeiro/pagar') },
      'k-equipe': { tipo: 'kpi', html: () => { const dom = new Date(hoje() + 'T12:00:00Z').getUTCDay() === 0, ult = !hojeAp.length && dom ? db.apont.map((a) => a.dia).filter((d) => d < hoje()).sort().pop() : '', ap = ult ? db.apont.filter((a) => a.dia === ult) : hojeAp, f = db.trab.filter((x) => !ap.some((a) => a.trab === x.id));
        return numero('equipe', ult ? 'Equipe no último dia de obra' : 'Equipe hoje', `${ap.length} de ${db.trab.length} vieram`, (ult ? `${dataBR(ult)} (hoje é domingo) · ` : '') + (f.length ? `faltaram: ${t(f.map((x) => x.nome.split(' ')[0]).join(', '))}` : 'todos apontados'), 'equipes'); } },
      'k-lucro': { tipo: 'kpi', html: () => numero('porcento', 'Lucro previsto das obras', R0(soma(and, lucro)), and.filter(risco).length ? `${pl(and.filter(risco).length, 'obra gastando', 'obras gastando')} acima do previsto` : 'nenhuma gastando acima do previsto', and[0] ? `obra/${(and.find(risco) || and[0]).id}/financeiro` : 'obras') },
      obras: { tipo: 'meia', html: () => `<div class="cartao"><div class="cartao-cab"><h2>Obras</h2><button type="button" class="bt pq" data-ir="obras">Ver todas</button></div>${and.length ? and.map(linhaObra).join('') : vazio('Nenhuma obra em andamento.', `<button type="button" class="bt cheio" data-acao="obra-nova">${ico('mais2')}Nova obra</button>`)}</div>` },
      atencao: { tipo: 'meia', html: () => {
        const atn = [];
        db.obras.forEach((o) => { o.medicoes.filter((m) => m.status === 'aberta').forEach((m) => atn.push([`Medição de ${R$(m.valor)} esperando o cliente`, o.nome, `obra/${o.id}/medicoes`])); o.aditivos.filter((a) => a.status === 'enviado').forEach((a) => atn.push([`Aditivo esperando aprovação: ${a.desc}`, o.nome, `obra/${o.id}/aditivos`])); });
        db.pedidos.filter((p) => p.status !== 'chegou' && p.prev <= somaDias(hoje(), 1)).forEach((p) => atn.push([`Material para chegar ${quando(p.prev)}: ${p.itens.map((i) => i.desc).join(', ')}`, obra(p.obra)?.nome || '', `obra/${p.obra}/compras`]));
        ms.filter(vencido).forEach((m) => atn.push([`${m.tipo === 'pagar' ? 'Conta vencida' : 'Recebimento atrasado'}: ${m.desc}`, R$(m.valor), `financeiro/${m.tipo}`]));
        return `<div class="cartao"><h2>Pede atenção</h2>${atn.length ? `<ul class="lista">${atn.slice(0, 7).map(([a, b, h]) => `<li><button type="button" class="item-bt" data-ir="${h}"><span class="ponto and"></span><span class="tx"><b>${t(a)}</b><small>${t(b)}</small></span>${ico('frente')}</button></li>`).join('')}</ul>${atn.length > 7 ? `<p class="mudo peq">e mais ${atn.length - 7} nas obras e no financeiro</p>` : ''}` : '<p class="mudo">Tudo em dia.</p>'}</div>`; } },
      cronograma: { tipo: 'larga', pc: true, html: () => { const sel = and.find((o) => o.id === db.config.ganttObra) || and[0]; return sel ? `<div class="cartao so-pc"><div class="cartao-cab"><h2>Cronograma</h2><select class="ent" style="max-width:300px" data-gantt-obra aria-label="Obra do cronograma">${and.map((o) => `<option value="${o.id}" ${o === sel ? 'selected' : ''}>${t(o.nome)}</option>`).join('')}</select></div>${gantt(sel, false)}</div>` : ''; } },
      canteiro: { tipo: 'larga', html: () => { const fotos = db.obras.flatMap((o) => o.diario.flatMap((d) => (d.fotos || []).map((f) => ({ f, o, d })))).sort((a, b) => b.d.dia.localeCompare(a.d.dia)).slice(0, 3);
        return `<div class="cartao"><div class="cartao-cab"><h2>Hoje no canteiro</h2><button type="button" class="bt pq" data-ir="diario">${ico('foto')}Registrar fotos</button></div>${fotos.length ? `<div class="fotos fotos-painel">${fotos.map(({ f, o, d }) => `<figure><img src="${t(f)}" alt="Foto do diário de ${t(o.nome)}" loading="lazy"><figcaption>${t(d.texto)}<small>${t(o.nome)} · ${dataBR(d.dia)}</small></figcaption></figure>`).join('')}</div>` : vazio('Nenhuma foto no diário ainda.')}</div>`; } },
      resultado: { tipo: 'meia', html: () => `<div class="cartao"><div class="cartao-cab"><h2>Lucro de cada obra</h2><button type="button" class="bt pq" data-ir="obras">Obras</button></div>${and.length ? `<ul class="lista">${and.map((o) => { const r = risco(o), l = lucro(o); return `<li><button type="button" class="item-bt" data-ir="obra/${o.id}/financeiro"><span class="tx"><b>${t(o.nome)}</b><small>contrato ${R$(contrato(o))} · custo orçado ${R$(custoOrc(o))}${r ? ` · <span class="vermelho forte">gasto ${pc(r)} acima do previsto</span>` : ' · gasto dentro do previsto'}</small></span><span class="val">${R$(l)}<small>${contrato(o) ? pc(l / contrato(o) * 100) : ''} de lucro</small></span></button></li>`; }).join('')}</ul>` : vazio('Nenhuma obra em andamento.')}</div>` },
      medicoes: { tipo: 'meia', html: () => { const ab = db.obras.flatMap((o) => o.medicoes.filter((m) => m.status === 'aberta').map((m) => ({ o, m }))), ap = db.fin.filter((f) => f.obra && f.tipo === 'receber' && !f.pago);
        return `<div class="cartao"><div class="cartao-cab"><h2>Medições e cobrança</h2><button type="button" class="bt pq" data-ir="financeiro/receber">A receber</button></div><ul class="lista">${ab.map(({ o, m }) => `<li><button type="button" class="item-bt" data-ir="obra/${o.id}/medicoes"><span class="ponto and"></span><span class="tx"><b>Esperando o cliente aprovar</b><small>${t(o.nome)} · medição de ${dataBR(m.dia)}</small></span><span class="val">${R$(m.valor)}</span></button></li>`).join('')}${ap.slice(0, 5).map((f) => `<li><button type="button" class="item-bt" data-ir="obra/${f.obra}/financeiro"><span class="ponto ${f.venc < hoje() ? '' : 'ok'}"></span><span class="tx"><b>${f.venc < hoje() ? 'Aprovado e atrasado' : 'Aprovado, a receber'}</b><small>${t(f.desc)} · vence ${dataBR(f.venc)}</small></span><span class="val">${R$(f.valor)}</span></button></li>`).join('')}</ul>${ab.length || ap.length ? '' : '<p class="mudo">Nenhuma medição esperando nem nada a receber.</p>'}</div>`; } },
      semana: { tipo: 'meia', html: () => { const ini = somaDias(hoje(), -6), ap = db.apont.filter((a) => !a.fechado && a.dia >= ini), por = db.trab.map((x) => { const l = ap.filter((a) => a.trab === x.id); return { x, d: soma(l, (a) => a.dias), v: soma(l, custoDiaria) }; }).filter((r) => r.d);
        return `<div class="cartao"><div class="cartao-cab"><h2>Diárias da semana</h2><button type="button" class="bt pq" data-ir="equipes/semana">Fechar a semana</button></div><p class="mudo peq" style="margin:-4px 0 6px">Últimos 7 dias, ainda não pagos (½ = meio dia)</p>${por.length ? `<ul class="lista">${por.map((r) => `<li><div class="tx"><b>${t(r.x.nome)}</b><small>${n2(r.d, 1)} ${r.d === 1 ? 'dia' : 'dias'} × ${R$(r.x.diaria)}</small></div><div class="val">${R$(r.v)}</div></li>`).join('')}</ul><p class="forte" style="margin-top:8px;text-align:right">A pagar na sexta: ${R$(soma(por, (r) => r.v))}</p>` : '<p class="mudo">Nenhuma diária aberta nos últimos 7 dias.</p>'}</div>`; } },
      compras: { tipo: 'meia', html: () => { const l = db.pedidos.filter((p) => p.status !== 'chegou').sort((a, b) => a.prev.localeCompare(b.prev));
        return `<div class="cartao"><div class="cartao-cab"><h2>Material para chegar</h2><button type="button" class="bt pq" data-ir="compras">Compras</button></div>${l.length ? `<ul class="lista">${l.slice(0, 6).map((p) => `<li><button type="button" class="item-bt" data-ir="obra/${p.obra}/compras"><span class="ponto ${p.prev < hoje() ? '' : 'and'}"></span><span class="tx"><b>${t(p.itens.map((i) => i.desc).join(', '))}</b><small>${t(obra(p.obra)?.nome || '')} · ${p.prev < hoje() ? `<span class="vermelho">atrasado desde ${dataBR(p.prev)}</span>` : `chega ${quando(p.prev)}`}</small></span></button></li>`).join('')}</ul>` : '<p class="mudo">Nenhum pedido esperando.</p>'}</div>`; } },
      cliente: { tipo: 'meia', html: () => `<div class="cartao"><div class="cartao-cab"><h2>Notícia para o cliente</h2><button type="button" class="bt pq" data-ir="diario">${ico('foto')}Diário</button></div>${and.length ? `<ul class="lista">${and.map((o) => { const u = o.diario.map((d) => d.dia).sort().pop(), n = u ? dias(u, hoje()) : 99; return `<li><div class="tx"><b>${t(o.nome)}</b><small>${t(nomeDe(o.cliente))} · ${u ? (n > 3 ? `<span class="vermelho forte">sem notícia há ${pl(n, 'dia', 'dias')}</span>` : `último diário ${quando(u)}`) : '<span class="vermelho forte">nenhum diário ainda</span>'}</small></div><button type="button" class="bt pq zap" data-acao="cli-zap" data-id="${o.id}">${ico('zap')}Mandar o link</button></li>`; }).join('')}</ul><p class="mudo peq" style="margin-top:8px">O link mostra as etapas, as fotos e os pagamentos; nunca o seu custo.</p>` : vazio('Nenhuma obra em andamento.')}</div>` },
      orcamentos: { tipo: 'meia', html: () => `<div class="cartao"><div class="cartao-cab"><h2>Orçamentos em aberto</h2><button type="button" class="bt pq" data-acao="obra-nova" data-status="orcamento">${ico('mais2')}Novo orçamento</button></div>${orcO.length ? `<ul class="lista">${orcO.map((o) => `<li><button type="button" class="item-bt" data-ir="obra/${o.id}/orcamento"><span class="tx"><b>${t(o.nome)}</b><small>${t(nomeDe(o.cliente))} · ${pl(o.orc.length, 'item', 'itens')}</small></span><span class="val">${R$(vendaOrc(o))}</span></button></li>`).join('')}</ul>` : '<p class="mudo">Nenhum orçamento em aberto.</p>'}</div>` },
    };
  },
  montar(el) { $('[data-gantt-obra]', el)?.addEventListener('change', (e) => { db.config.ganttObra = e.target.value; grava(); }); },
};
function linhaObra(o) {
  const f = fotoObra(o), fis = fisico(o), fin = financeiro(o);
  return `<button type="button" class="obra-lin" data-ir="obra/${o.id}">${f ? `<img src="${t(f)}" alt="" loading="lazy">` : `<span class="sem-foto"></span>`}<span><b>${t(o.nome)}</b><small>${t(nomeDe(o.cliente))} · entrega ${dataBR(o.fim)}</small>${(() => { const p = previsto(o), g = realizado(o).total; return p > 0 && g > p * 1.05 ? `<small class="vermelho forte">gasto ${pc((g - p) / p * 100)} acima do previsto</small>` : atrasoDias(o) ? `<small class="vermelho forte">atrasada ${pl(atrasoDias(o), 'dia', 'dias')}</small>` : ''; })()}</span>
    <span class="pct"><b>${pc(fis)}</b>${barra(fis)}<small class="mudo" style="grid-column:1/-1">físico</small></span><span class="pct"><b>${pc(fin)}</b>${barra(fin, 'pri')}<small class="mudo" style="grid-column:1/-1">recebido</small></span></button>`;
}

// ------------------------------------------------------------------ Gantt simples
function gantt(o, editavel = true) {
  if (!o.etapas.length) return vazio('Nenhuma etapa ainda.');
  const ini = o.etapas.reduce((m, e) => (e.ini < m ? e.ini : m), o.etapas[0].ini), fim = o.etapas.reduce((m, e) => (e.fim > m ? e.fim : m), o.etapas[0].fim);
  const total = Math.max(7, dias(ini, fim) + 1), porMes = total > 120, passo = porMes ? 30 : 7, cols = Math.ceil(total / passo);
  const pos = (d) => Math.max(0, Math.min(100, dias(ini, d) / total * 100)), h = pos(hoje());
  return `<div class="tab-wrap"><div class="gantt" style="min-width:560px"><div class="gantt-cab"><span>Etapa</span><div class="gantt-semanas" style="grid-template-columns:repeat(${cols},1fr)">${Array.from({ length: cols }, (_, i) => `<span>${porMes ? dataCurta(somaDias(ini, i * 30)).slice(3) + '/' + somaDias(ini, i * 30).slice(2, 4) : 'Sem ' + (i + 1)}</span>`).join('')}</div></div>
    ${o.etapas.map((e) => `<div class="gantt-nome"><span class="ponto ${e.pct >= 100 ? 'ok' : e.pct > 0 ? 'and' : ''}"></span>${editavel ? `<button type="button" data-acao="etapa-ed" data-obra="${o.id}" data-id="${e.id}">${t(e.nome)}</button>` : `<span style="font-weight:650">${t(e.nome)}</span>`}</div>
      <div class="gantt-trilho" style="--sem:${100 / cols}%">${hoje() >= ini && hoje() <= fim ? `<span class="gantt-hoje" style="left:${h}%" title="Hoje"></span>` : ''}<div class="gantt-barra ${e.pct >= 92 ? 'cheia' : ''}" style="left:${pos(e.ini)}%;width:${Math.max(2, pos(e.fim) - pos(e.ini))}%" title="${t(e.nome)}: ${dataBR(e.ini)} a ${dataBR(e.fim)}"><i style="width:${e.pct}%"></i>${pos(e.fim) - pos(e.ini) >= 7 ? `<b>${e.pct}%</b>` : ''}</div></div>`).join('')}</div></div>
    <p class="mudo peq" style="margin-top:8px">${dataBR(ini)} a ${dataBR(fim)} · linha amarela: hoje${editavel ? ' · toque no nome da etapa para mudar datas e o quanto já foi feito' : ''}</p>`;
}
// etapa atrasada: nova data com o motivo, e o impacto na entrega da obra
