      const o = { id: uid('o'), ...d, foto: '', token: uid('k'), etapas: [], orc: [], valor: 0, medicoes: [], aditivos: [], diario: [], docs: [] }; delete o.padrao;
      if (d.padrao) { const MOD = (MODELOS[d.tipo] || MODELOS.residencial)[1], tot = dias(d.inicio, d.fim), soma2 = MOD.reduce((s, e) => s + e[1], 0); let ini = d.inicio; MOD.forEach(([nome, p]) => { const dur = Math.max(3, Math.round(tot * p / soma2 * 1.25)); const fim = somaDias(ini, dur) > d.fim ? d.fim : somaDias(ini, dur); o.etapas.push({ id: uid('e'), nome, ini, fim, pct: 0 }); ini = somaDias(ini, Math.round(dur * 0.8)); if (ini > d.fim) ini = d.fim; }); }
